function getEffectiveness(moveType, defType1, defType2) {
	const row = TYPE_CHART[moveType];
	if (!row) return 1;
	return (defType1 in row ? row[defType1] : 1) * (defType2 && defType2 in row ? row[defType2] : 1);
}
